<?php
    $format = data_get($research->metadata, 'research_setup', []);
    $font = ($format['format_font'] ?? '') === 'sans-serif' ? 'DejaVu Sans, Arial, sans-serif' : 'DejaVu Serif, Times New Roman, serif';
    $size = max(10, min(14, (int)($format['format_size'] ?? 12)));
    $spacing = max(1, min(2, (float)($format['format_spacing'] ?? 1.5)));
    $margin = max(15, min(40, (int)($format['format_margin'] ?? 25)));
    $bibliography = app(\App\Services\ResearchDocumentExportService::class)->bibliography($research);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><title><?php echo e($research->title); ?> · AcadSyntra</title><style>@page{size:A4;margin:<?php echo e($margin); ?>mm}body{font-family:<?php echo $font; ?>;font-size:<?php echo e($size); ?>pt;line-height:<?php echo e($spacing); ?>;color:#172033}h1{font-size:24pt;text-align:center}h2{font-size:17pt;page-break-after:avoid}h3{font-size:14pt;page-break-after:avoid}.meta{color:#64748b;text-align:center;font-size:10pt}.contents{page-break-after:always}.section{page-break-before:always}a{color:inherit}table{width:100%;border-collapse:collapse}td,th{border:1px solid #cbd5e1;padding:6px}img{max-width:100%}pre{white-space:pre-wrap;overflow-wrap:break-word}</style></head><body><h1><?php echo e($research->title); ?></h1><p class="meta"><?php echo e($research->owner?->full_name); ?> · <?php echo e($format['institution_name'] ?? $research->department?->name); ?> · <?php echo e($format['method']['label'] ?? $research->researchType?->name); ?></p><div class="contents"><h2>Contents</h2><ol><?php $__currentLoopData = $research->sections; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $section): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><li><a href="#section-<?php echo e($section->uuid); ?>"><?php echo e($section->title); ?></a></li><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></ol></div><?php $__currentLoopData = $research->sections; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $section): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><section class="section" id="section-<?php echo e($section->uuid); ?>"><h2><?php echo e($section->title); ?></h2><?php if($section->key === 'references' && trim(strip_tags((string)$section->document?->body)) === ''): ?><?php $__currentLoopData = $bibliography; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $entry): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><p><?php echo e($entry); ?></p><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?> <?php else: ?><?php echo app(\App\Services\RichTextSanitizer::class)->sanitize((string) ($section->document?->body ?? '')); ?><?php endif; ?></section><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></body></html>
